insert into public.exercises(id,name,english_name,description,category,equipment,primary_muscle,instructions,tips,mistakes,load_kind,supports_1rm) values ('10000000-0000-4000-8000-000000000001','Développé couché','Bench press','Sur un banc plat, abaissez la barre vers le bas des pectoraux puis poussez sans décoller les appuis.','Polyarticulaire','Barre','Pectoraux',array['Réglez le matériel et choisissez une charge permettant un mouvement maîtrisé.','Sur un banc plat, abaissez la barre vers le bas des pectoraux puis poussez sans décoller les appuis.','Revenez lentement à la position de départ, respirez et répétez sans à-coups.'],'Conservez des appuis stables et une amplitude confortable. Pour un mouvement unilatéral, notez la charge d’un côté et les répétitions par côté, de manière constante.','Évitez l’élan, les amplitudes forcées et une charge qui dégrade votre exécution. Sur haltères, consignez toujours la charge par haltère ; ne la doublez pas dans l’historique.','external',true) on conflict(id) do nothing;
